import {timing,loopRange,setLoop,setTempo,fromSeconds,toSeconds,formatTime} from '../animation/timing.js';
import {copySequence,pasteSequence,extendDuration} from '../animation/sequence.js';
export function syncTempoMeasurement(a){const unit=a.doc.playback?.measurement||'seconds';if(!['seconds','frames','bars'].includes(unit))return;if(a.timeline)a.timeline.measurement=unit;const select=document.querySelector('#timeline-units');if(select)select.value=unit;}
export function showTempo(a){
 a.pause();a.properties.flush();a.stage.finishPath();const clock=timing(a.doc),range=loopRange(a.doc),d=a.dialog('Sequencer tempo',`<form><div class="dialog-grid"><label>Tempo (BPM)<input name="bpm" type="number" min="20" max="300" step="any" value="${clock.bpm}" required></label><label>Beats per bar<input name="beats" type="number" min="1" max="16" step="1" value="${clock.beatsPerBar}" required></label><label>Timeline measurement<select name="unit">${['seconds','frames','bars'].map(unit=>`<option value="${unit}" ${unit===a.timeline.measurement?'selected':''}>${unit[0].toUpperCase()+unit.slice(1)}</option>`).join('')}</select></label></div><p data-tempo-preview role="status"></p><p class="subtle">Tempo changes bar measurement. Existing keyframes, audio, composition duration and playback-loop times stay in place. To change the loop itself, choose Loop range.</p><div class="dialog-actions"><button type="button" data-close>Cancel</button><button type="submit" class="primary">Apply tempo</button></div></form>`,(form,dialog)=>{a.mutate('Sequencer tempo',()=>setTempo(a.doc,Number(form.get('bpm')),Number(form.get('beats')),form.get('unit')));syncTempoMeasurement(a);a.render();dialog.close();a.toast('Tempo saved; animation timing unchanged.');});
 const preview=()=>{const bpm=Number(d.querySelector('[name=bpm]').value),beats=Number(d.querySelector('[name=beats]').value),valid=Number.isFinite(bpm)&&bpm>=20&&bpm<=300&&Number.isInteger(beats)&&beats>=1&&beats<=16;d.querySelector('[data-tempo-preview]').textContent=valid?`1 bar = ${Number((60/bpm*beats).toFixed(3))}s · ${Number((60/bpm*beats*a.doc.fps).toFixed(2))} frames. Current loop: ${Number((range.end-range.start).toFixed(3))}s (${Number(((range.end-range.start)*bpm/60/beats).toFixed(3))} bars).`:'Enter a valid tempo and beats per bar.';};d.querySelectorAll('input,select').forEach(input=>input.addEventListener('input',preview));preview();return d;
}
export function showSequence(a){
 a.pause();a.properties.flush();a.stage.finishPath();const timeline=a.timeline,range=loopRange(a.doc),clock=timing(a.doc),d=a.dialog('Sequence & duration',`<fieldset class="loop-settings"><legend>Playback loop</legend><div class="dialog-grid"><label>Start<input data-loop-start type="number" min="0" step="any" value="${fromSeconds(a.doc,range.start,timeline.measurement)}"></label><label>Loop length<input data-loop-length type="number" min=".001" step="any" value="${fromSeconds(a.doc,range.end-range.start,timeline.measurement)}"></label><label>Measurement<select data-loop-unit><option value="seconds" ${timeline.measurement==='seconds'?'selected':''}>Seconds</option><option value="frames" ${timeline.measurement==='frames'?'selected':''}>Frames</option><option value="bars" ${timeline.measurement==='bars'?'selected':''}>Bars</option></select></label><label>Tempo (BPM)<input data-loop-bpm type="number" min="20" max="300" value="${clock.bpm}"></label><label>Beats per bar<input data-loop-beats type="number" min="1" max="16" step="1" value="${clock.beatsPerBar}"></label></div><p data-loop-preview role="status"></p><div class="dialog-actions"><button data-loop-playhead>Start at playhead</button><button data-loop-whole>Whole composition</button><button data-loop-apply class="primary">Apply playback loop</button></div></fieldset><p>Copy the animation tracks of selected layers, or the whole composition. Paste repeats them on the same layers. Projects and audio stay on this device.</p><div class="dialog-grid"><label>Copy scope<select data-sequence-scope><option value="selected" ${a.selected.length?'':'disabled'}>${a.selected.length?'Selected layers':'Select layers first'}</option><option value="all" ${a.selected.length?'':'selected'}>All layers</option></select></label><label>Paste position<select data-sequence-position><option value="end">Append at end</option><option value="playhead">At playhead (replace overlapping keys)</option></select></label></div><div class="dialog-actions"><button data-copy-sequence>Copy sequence</button><button data-paste-sequence>Paste sequence</button></div><p class="sequence-status" role="status"></p><p class="sequence-preview"></p><fieldset><legend>Add time</legend><label>Seconds to add<input data-extra-seconds aria-label="Seconds to add" type="number" min="${1/a.doc.fps}" max="600" step="${1/a.doc.fps}" value="2"></label><button data-extend-time>+ Add seconds</button><p class="subtle">This extends the composition without stretching existing keyframes or audio.</p></fieldset><label>Timeline measurement<select data-measurement aria-label="Timeline measurement"><option value="seconds" ${timeline.measurement==='seconds'?'selected':''}>Seconds</option><option value="frames" ${timeline.measurement==='frames'?'selected':''}>Frames</option><option value="bars" ${timeline.measurement==='bars'?'selected':''}>Bars</option></select></label>`);
 const draftClock=()=>({...a.doc,playback:{...a.doc.playback,bpm:Number(d.querySelector('[data-loop-bpm]').value),beatsPerBar:Number(d.querySelector('[data-loop-beats]').value)}});let oldUnit=timeline.measurement;const loopPreview=()=>{const bpm=Number(d.querySelector('[data-loop-bpm]').value),beats=Number(d.querySelector('[data-loop-beats]').value),unit=d.querySelector('[data-loop-unit]').value,value=Number(d.querySelector('[data-loop-length]').value),seconds=unit==='bars'?value*60/bpm*beats:toSeconds(a.doc,value,unit);d.querySelector('[data-loop-preview]').textContent=Number(seconds.toFixed(3))+'s · '+Math.round(seconds*a.doc.fps)+' frames'+(unit==='bars'?' · '+value+' bars · '+beats+' beats/bar at '+bpm+' BPM':'');};
 d.querySelector('[data-loop-unit]').onchange=e=>{const first=toSeconds(draftClock(),Number(d.querySelector('[data-loop-start]').value),oldUnit),length=toSeconds(draftClock(),Number(d.querySelector('[data-loop-length]').value),oldUnit);d.querySelector('[data-loop-start]').value=fromSeconds(draftClock(),first,e.target.value);d.querySelector('[data-loop-length]').value=fromSeconds(draftClock(),length,e.target.value);oldUnit=e.target.value;loopPreview();};
 d.querySelectorAll('.loop-settings input').forEach(input=>input.oninput=loopPreview);
 d.querySelector('[data-loop-playhead]').onclick=()=>{d.querySelector('[data-loop-start]').value=fromSeconds(draftClock(),a.time,oldUnit);loopPreview();};
 d.querySelector('[data-loop-whole]').onclick=()=>{d.querySelector('[data-loop-start]').value=0;d.querySelector('[data-loop-length]').value=fromSeconds(draftClock(),a.doc.duration,oldUnit);loopPreview();};
 d.querySelector('[data-loop-apply]').onclick=()=>a.safe(()=>{a.mutate('Playback loop',()=>setLoop(a.doc,Number(d.querySelector('[data-loop-start]').value),Number(d.querySelector('[data-loop-length]').value),oldUnit,Number(d.querySelector('[data-loop-bpm]').value),Number(d.querySelector('[data-loop-beats]').value)));a.loop=true;a.render();loopPreview();a.toast('Playback loop saved.');});loopPreview();
 const status=()=>{const s=timeline.sequenceClipboard;d.querySelector('.sequence-status').textContent=`Composition: ${Number(a.doc.duration.toFixed(3))}s · ${Math.round(a.doc.duration*a.doc.fps)} frames at ${a.doc.fps} fps.${s?' Copied: '+s.tracks.length+' tracks · '+s.duration+'s.':''}`;d.querySelector('[data-paste-sequence]').disabled=!s?.tracks.length;const start=d.querySelector('[data-sequence-position]').value==='end'?a.doc.duration:a.time,total=s?Math.max(a.doc.duration,start+s.duration):a.doc.duration;let overlap=0;if(s)for(const t of s.tracks){const visit=list=>{for(const n of list){if(n.id===t.object)overlap+=(n.tracks[t.prop]||[]).filter(k=>t.keys.some(source=>Math.abs(k.time-Math.round((start+source.time)*a.doc.fps)/a.doc.fps)<.00001)).length;visit(n.children||[]);}};visit(a.doc.layers);}d.querySelector('.sequence-preview').textContent=s?'Paste '+Math.round(s.duration*a.doc.fps)+' frames across '+s.tracks.length+' tracks at frame '+Math.round(start*a.doc.fps)+' → total '+Math.ceil(total*a.doc.fps)+' frames ('+Number(total.toFixed(3))+'s). '+overlap+' overlapping keys will be replaced. Audio is not copied.':'';};
 d.querySelector('[data-copy-sequence]').onclick=()=>a.safe(()=>{timeline.sequenceClipboard=copySequence(a.doc,d.querySelector('[data-sequence-scope]').value==='selected'?a.selected:[]);if(!timeline.sequenceClipboard.tracks.length)a.toast('Add keyframes before copying a sequence.');status();});
 d.querySelector('[data-paste-sequence]').onclick=()=>a.safe(()=>{const start=d.querySelector('[data-sequence-position]').value==='end'?a.doc.duration:a.time;a.mutate('Paste animation sequence',()=>{a.keyIds=new Set(pasteSequence(a.doc,timeline.sequenceClipboard,start));});a.seek(start);a.timeline.render();status();});
 d.querySelector('[data-extend-time]').onclick=()=>a.safe(()=>{const seconds=Number(d.querySelector('[data-extra-seconds]').value);a.mutate('Extend composition',()=>extendDuration(a.doc,seconds));status();});
 d.querySelector('[data-measurement]').onchange=e=>{const measurement=e.target.value;a.mutate('Timeline measurement',()=>setTempo(a.doc,timing(a.doc).bpm,timing(a.doc).beatsPerBar,measurement));syncTempoMeasurement(a);a.render();status();};d.querySelector('[data-sequence-position]').onchange=status;status();return d;
}
